// ─── File: src/main/java/com/bank/core/VaultAccount.java ───
package com.bank.core;

import java.io.*;

// Inherits Serializable from Account, but MUST NOT be serialized.
public class VaultAccount extends Account {
    private static final long serialVersionUID = 1L;
    private final String vaultId;

    public VaultAccount(String accountId, java.math.BigDecimal balance, String vaultId) {
        super(accountId, balance);
        this.vaultId = vaultId;
    }
    public String getVaultId() { return vaultId; }

    // Block serialization in BOTH directions with a loud, naming exception.
    private void writeObject(ObjectOutputStream out) throws IOException {
        throw new NotSerializableException(VaultAccount.class.getName());
    }
    private void readObject(ObjectInputStream in) throws IOException {
        throw new NotSerializableException(VaultAccount.class.getName());
    }
}
```

```java
// ─── File: src/main/java/com/bank/core/RestrictSubclassDemo.java ───
package com.bank.core;

import java.io.*;
import java.math.BigDecimal;
import java.util.logging.*;

public class RestrictSubclassDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    private static byte[] serialize(Object o) throws IOException {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        try (ObjectOutputStream oos = new ObjectOutputStream(buffer)) {
            oos.writeObject(o);
        }
        return buffer.toByteArray();
    }

    public static void main(String[] args) {
        // Ordinary account serializes fine (parent is Serializable).
        try {
            byte[] ok = serialize(new Account("SAV2001", new BigDecimal("1000000.00")));
            log.info(() -> "Ordinary Account serialized OK, bytes = " + ok.length);
        } catch (IOException e) {
            log.log(Level.SEVERE, "Unexpected failure for Account", e);
        }

        // VaultAccount is blocked even though it inherits Serializable.
        try {
            serialize(new VaultAccount("VLT9001", new BigDecimal("50000000.00"), "VAULT-A"));
            log.severe("BUG: VaultAccount should NOT have serialized");
        } catch (NotSerializableException e) {
            log.log(Level.SEVERE, "VaultAccount serialization correctly rejected", e);
        } catch (IOException e) {
            log.log(Level.SEVERE, "Other IO error", e);
        }
    }
}
```
